// 1. Obtenemos el Request Original
var requestOriginal = vars.RequestOrder 

// 2. Función de navegación segura
fun resolvePath(obj: Any, path: String) = 
    if (path != null) 
        path splitBy "." reduce (key, acc = obj) -> acc[key]
    else null

// 3. Construimos el filtro dinámico basado en las reglas
var dynamicMatch = payload.accion.evaluacionRequest reduce (item, acc = {}) -> (
    if (item.parametro != null and item.valor != null)
        do {


             // Resolvemos el valor real del request usando el path elegido
           var valorReal =
    if ((item.parametro default "") == "==" or isEmpty(item.parametro default ""))
        item.comparacion
    else
        resolvePath(requestOriginal, item.parametro)
            // Construimos la llave final (root o dot notation)
            var llaveFinal = if (item.contenedor == "root") item.valor 
                             else (item.contenedor ++ "." ++ item.valor)
// --- LÓGICA DE TRANSFORMACIÓN DE VALOR ---
            var valorFinal = if (item.valor == "_id") 
                                { "\$oid": valorReal } // Si es _id, aplicamos formato ObjectId
                             else if (item.usaRegex == true) 
                                { "\$regex": valorReal } 
                             else 
                                valorReal
            ---
            acc ++ { (llaveFinal): valorFinal }
        }
    else acc
)

---
{
  "query": {
    "aggregate": payload.accion.coleccion,
    "pipeline": [
      {
        // Envolvemos el resultado en un $match para que Mongo filtre
        "\$match": dynamicMatch
      }
    ],
    "cursor": {}
  }
}

