%dw 2.0
output application/json

// Importamos la librería de fechas
import * from dw::core::Dates

// 1. Datos de origen (usando tus nombres de variables actuales)
var requestOriginal = vars.RequestOrder 
var mongoResponse = payload default {} 
var validaciones = vars.currentRule.accion.evaluacionRespuesta default []

// --- FUNCIONES CORE ---
fun resolvePath(obj: Any, path: Any, isManual: Boolean = false) = do {
    var isSizeRequest = (path as String) matches /size\(.*\)/
    var cleanPath = if (isSizeRequest) 
                        (path as String) replace "size(" with "" replace ")" with ""
                    else path as String

    var fullPath = if (isManual) cleanPath
                   else if (cleanPath contains "payload.") cleanPath replace "payload." with "" 
                   else if (cleanPath contains "result.") cleanPath
                   else "result[0]." ++ cleanPath
    ---
    do {
        var extractedData = (fullPath as String) splitBy "." reduce (key, acc = obj) -> (
            if (acc == null) null 
            else if (key contains "[") do {
                var parts = key splitBy "["
                var attr = parts[0]
                var index = (parts[1] replace "]" with "") as Number
                ---
                if (acc[attr] != null) acc[attr][index] else null
            } else acc[key]
        )
        ---
        if (isSizeRequest) 
            if (extractedData is Array) sizeOf(extractedData)
            else if (extractedData is Object) sizeOf(keysOf(extractedData))
            else if (extractedData == null) 0
            else 1
        else extractedData
    }
}

fun getExpectedValue(expected: Any) = 
    if (expected != null and expected is String and (expected matches /\{\{.*\}\}/)) do {
        var pathReq = expected replace "{{" with "" replace "}}" with ""
        ---
        (pathReq as String) splitBy "." reduce (key, acc = requestOriginal) -> acc[key]
    }
    else expected

fun checkCondition(actual, operator, expected) = do {
    var a = if (actual != null and !(actual is Array) and !(actual is Object)) trim(actual as String) else actual
    var e = if (expected != null and !(expected is Array) and !(expected is Object)) trim(expected as String) else expected
    ---
    operator match {
        case "exists" -> actual != null
        case "not_exists" -> actual == null
        case "max_30_days" -> do {
            var hoy = now() as Date
            var fechaEvaluar = actual as Date default null
            ---
            if (fechaEvaluar != null) abs(daysBetween(fechaEvaluar, hoy)) <= 30 else false
        }
        case ">" -> (actual default 0) > (expected default 0)
        case "==" -> a == e
        case "!=" -> a != e
        case "is_not_empty" -> !isEmpty(actual)
        else -> false
    }
}

// --- PROCESAMIENTO ---
var listaResultados = validaciones map (item) -> do {
    var categoriaRequest = lower(requestOriginal.category default "")
    var pathFinalMongo = if (item.campoResultado contains "{category}")
                            if (categoriaRequest == "lte") 
                                item.campoResultado replace "{category}" with "score_movil"
                            else 
                                item.campoResultado replace "{category}" with "score_fija"
                         else 
                            item.campoResultado

    var isManual = (item.tipoEvaluacion default "") == "MANUAL"
    var valorEnMongo = resolvePath(mongoResponse, pathFinalMongo default "", false)
    var valorAComparar = if (isManual)
                            resolvePath(requestOriginal, item.valorEsperado default "", true)
                         else
                            getExpectedValue(item.valorEsperado)

    var cumpleCondicion = checkCondition(valorEnMongo, item.logica, valorAComparar)
    ---
    {
        descripcion: item.descripcion,
        resultado: if (cumpleCondicion) "OK" else "FALLO",
        comparacion: if (item.logica == "exists") 
                (if (cumpleCondicion) "El objeto existe" else "El objeto NO existe")
             else if (item.logica == "max_30_days")
                "$(valorEnMongo default 'null') no supera los 30 días respecto a hoy"
             else 
                "$(valorEnMongo default 'null') $(item.logica) $(valorAComparar default 'null')",
        critica: (not cumpleCondicion) and (item.obligatoria default false),
        obligatoria: item.obligatoria
    }
}

// --- SALIDA PARA SET VARIABLE ---
---
do {
    // 1. Tomamos lo que ya tiene la variable o inicializamos con vacío
    var acumulado = vars.reglasAcumuladas default []

    // 2. Creamos el objeto de la regla actual
    var resultadoActual = {
        idRegla: vars.currentRule.idRegla default "",
        obligatoria: vars.currentRule.obligatoria default "",
        evaluacionDetallada: listaResultados map (r) -> (r - "critica"),
        esValido: if (isEmpty(listaResultados)) true 
                  else not (listaResultados.critica contains true),
        respuestaRegla: if (not (listaResultados.critica contains true)) vars.currentRule.siSeCumple 
                        else vars.currentRule.siFalla,
        estadoOrdenComercial: vars.currentRule.estadoOrdenComercial
    }
    ---
    // 3. Retornamos la lista con el nuevo elemento al final
    acumulado ++ [resultadoActual]
}
